package main

import (
    "context"
    "time"
)

func fetchReceiptWithinBudget(
    parentContext context.Context,
    ledgerLookup func(context.Context) (string, error),
) (string, error) {
    lookupContext, cancelLookup := context.WithTimeout(parentContext, 430*time.Millisecond)
    defer cancelLookup()
    return ledgerLookup(lookupContext)
}

package main

import (
    "context"
    "net/http"
    "time"
)

func stopReceiptServer(receiptServer *http.Server) error {
    shutdownContext, cancelShutdown := context.WithTimeout(context.Background(), 9*time.Second)
    defer cancelShutdown()
    return receiptServer.Shutdown(shutdownContext)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

module "receipt_network" {
  source  = "app.terraform.io/ledger-team/network/aws"
  version = "3.4.2"
}

import {
  to = aws_s3_bucket.receipt_archive
  id = "receipt-archive-prod"
}

resource "aws_s3_bucket" "receipt_archive" {
  bucket = "receipt-archive-prod"
}

resource "aws_autoscaling_group" "receipt_workers" {
  name_prefix         = "receipt-workers-"
  max_size            = 6
  min_size            = 3
  desired_capacity    = 3
  vpc_zone_identifier = var.worker_subnet_ids

  lifecycle {
    create_before_destroy = true
  }
}

variable "receipt_db_password" {
  type      = string
  sensitive = true
}

locals {
  receipt_worker_groups = {
    "region-east" = 3
    "region-west" = 2
  }
}

resource "terraform_data" "worker_group_contract" {
  for_each = local.receipt_worker_groups
  input = {
    region_code = each.key
    target_size = each.value
  }
}

resource "aws_autoscaling_group" "receipt_workers" {
  name_prefix         = "receipt-workers-"
  max_size            = 8
  min_size            = 2
  desired_capacity    = 3
  vpc_zone_identifier = var.worker_subnet_ids

  lifecycle {
    ignore_changes = [desired_capacity]
  }
}

removed {
  from = aws_s3_bucket.receipt_archive

  lifecycle {
    destroy = false
  }
}

